using System;using System.Data;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class CommandCenterPage:UserControl{TextBox q;DataGridView grid;public CommandCenterPage(){Dock=DockStyle.Fill;BackColor=Theme.Background;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=60,Padding=new Padding(4)};q=Ui.Text();q.Width=500;var b=Ui.Button(L.Fa?"جستجوی سراسری":"Global search");b.Click+=(s,e)=>LoadData();q.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter)LoadData();};top.Controls.Add(q);top.Controls.Add(b);Controls.Add(top);grid=Ui.Grid();Controls.Add(grid);grid.BringToFront();LoadData();}void LoadData(){string x=q.Text.Trim();grid.DataSource=Database.Query(@"SELECT TOP 100 N'Job' Entity,CAST(Id AS NVARCHAR(20)) Id,Title Name,City Detail FROM Jobs WHERE @q='' OR Title LIKE @p OR City LIKE @p UNION ALL SELECT TOP 100 N'Candidate',CAST(Id AS NVARCHAR(20)),FullName,ISNULL(PrimarySkill,'') FROM Candidates WHERE @q='' OR FullName LIKE @p OR PrimarySkill LIKE @p UNION ALL SELECT TOP 100 N'Company',CAST(Id AS NVARCHAR(20)),Name,ISNULL(Industry,'') FROM Companies WHERE @q='' OR Name LIKE @p OR Industry LIKE @p",new SqlParameter("@q",x),new SqlParameter("@p","%"+x+"%"));}}}
